parameters.jsCode:
// Accede al primer item y su contenido JSON
const inputObject = items[0].json;

// Obtiene todos los valores (las URLs) del objeto
const urls = Object.values(inputObject);

// Crea un nuevo arreglo de items, donde cada item tiene una propiedad "url"
const outputItems = urls.map(url => {
  return {
    json: {
      "channels": url
    }
  };
});

// Devuelve el nuevo arreglo de items para que el flujo continúe
return outputItems;

// Iteramos sobre cada ítem (archivo) que llega.
// n8n opera sobre un array de objetos
for (const item of items) {

  // Verificamos que el ítem tenga datos binarios en la propiedad 'data'
  if (item.binary && item.binary.data) {
    const binaryData = item.binary.data;

    // --- 1. CORRECCIÓN DEL FILE NAME (LA MÁS IMPORTANTE) ---
    // La API de OpenAI necesita un nombre de archivo con extensión.

    const extension = binaryData.fileExtension; // ej: 'mp4' o 'mpga'

    // Si el 'fileName' no termina ya con la extensión correcta, la añadimos.
    if (extension && binaryData.fileName && !binaryData.fileName.endsWith(`.${extension}`)) {
      binaryData.fileName = `${binaryData.fileName}.${extension}`;
    }

    // --- 2. CORRECCIÓN DEL MIME TYPE (PREVENCIÓN) ---
    // Si el Mime Type es 'video/mp4', lo cambiamos a 'audio/mp4'.
    // Los otros ('audio/mpeg', 'audio/mp4') los dejamos como están.
    if (binaryData.mimeType === 'video/mp4') {
      binaryData.mimeType = 'audio/mp4';
    }
  }
}

// Devolvemos los ítems con los metadatos corregidos al nodo de OpenAI
return items;

